// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { link, readdir, readFile, symlink, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { FileView } from "../packages/app-backend/src/index.js";
import {
  appendFile,
  committedFile,
  fileDigest,
  fileJson,
  initiateFile,
} from "./backend-file-fixture.js";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";

describe("private resumable application files", () => {
  let fixture: BackendFixture, cookie: string;
  beforeEach(async () => {
    fixture = await backendFixture();
    cookie = (await fixture.register()).cookie;
  });
  afterEach(async () => fixture.close());

  it("T-AC-56 commits real private bytes, metadata and independently verified SHA-256", async () => {
    const { file, bytes } = await committedFile(fixture, cookie, "héllo private bytes 🛰️");
    expect(file).toMatchObject({
      status: "committed",
      size: bytes.byteLength,
      offset: bytes.byteLength,
      sha256: fileDigest(bytes),
    });
    const response = await fixture.request(`/files/${file.id}/download`, { headers: { cookie } });
    expect(response.status).toBe(200);
    expect(new Uint8Array(await response.arrayBuffer())).toEqual(bytes);
    expect(response.headers.get("content-type")).toContain("application/octet-stream");
    expect(response.headers.get("content-disposition")).toContain("attachment");
    expect(response.headers.get("cache-control")).toContain("no-store");
    expect(await readFile(join(fixture.filesRoot, file.id))).toEqual(Buffer.from(bytes));
  });

  it("T-AC-56 keeps incomplete uploads unreadable and resumes at the durable offset after restart", async () => {
    const bytes = new TextEncoder().encode("first-second");
    const initial = await initiateFile(fixture, cookie, bytes);
    const first = await appendFile(fixture, cookie, initial, bytes.subarray(0, 6));
    expect(first.status).toBe(200);
    const progress = FileView.parse(await first.json());
    expect(progress).toMatchObject({ offset: 6, status: "uploading" });
    expect(
      (await fixture.request(`/files/${initial.id}/download`, { headers: { cookie } })).status,
    ).toBe(404);
    await fixture.restart();
    const retained = FileView.parse(
      await (await fixture.request(`/files/${initial.id}`, { headers: { cookie } })).json(),
    );
    expect(retained).toEqual(progress);
    const second = await appendFile(fixture, cookie, retained, bytes.subarray(6));
    expect(second.status).toBe(200);
    const final = FileView.parse(await second.json());
    const complete = await fileJson(fixture, cookie, `/files/${initial.id}/complete`, {
      expectedRevision: final.revision,
    });
    expect(complete.status).toBe(200);
    expect(
      await (
        await fixture.request(`/files/${initial.id}/download`, { headers: { cookie } })
      ).text(),
    ).toBe("first-second");
  });

  it("T-AC-56 refuses stale offsets/revisions and never duplicates previously written bytes", async () => {
    const bytes = new TextEncoder().encode("abcdef");
    const initial = await initiateFile(fixture, cookie, bytes);
    const response = await appendFile(fixture, cookie, initial, bytes.subarray(0, 3));
    const progress = FileView.parse(await response.json());
    expect((await appendFile(fixture, cookie, initial, bytes.subarray(0, 3))).status).toBe(409);
    expect((await appendFile(fixture, cookie, progress, bytes.subarray(3), 0)).status).toBe(409);
    expect(await readFile(join(fixture.filesRoot, initial.id))).toEqual(Buffer.from("abc"));
  });

  it("T-AC-56 refuses completion until actual length and expected digest match", async () => {
    const bytes = new TextEncoder().encode("abc");
    const initial = await initiateFile(fixture, cookie, bytes, { sha256: "0".repeat(64) });
    expect(
      (
        await fileJson(fixture, cookie, `/files/${initial.id}/complete`, {
          expectedRevision: initial.revision,
        })
      ).status,
    ).toBe(409);
    const appended = FileView.parse(
      await (await appendFile(fixture, cookie, initial, bytes)).json(),
    );
    expect(
      (
        await fileJson(fixture, cookie, `/files/${initial.id}/complete`, {
          expectedRevision: appended.revision,
        })
      ).status,
    ).toBe(409);
    const stored = FileView.parse(
      await (await fixture.request(`/files/${initial.id}`, { headers: { cookie } })).json(),
    );
    expect(stored.status).toBe("uploading");
    expect(
      (await fixture.request(`/files/${initial.id}/download`, { headers: { cookie } })).status,
    ).toBe(404);
  });

  it("T-AC-56 replays initiation once and rejects changed body under the same key", async () => {
    const bytes = new TextEncoder().encode("replay");
    const key = randomUUID();
    const first = await initiateFile(fixture, cookie, bytes, {}, key);
    const second = await initiateFile(fixture, cookie, bytes, {}, key);
    expect(second).toEqual(first);
    const conflict = await fileJson(
      fixture,
      cookie,
      "/files",
      {
        name: "changed.txt",
        contentType: "text/plain",
        size: bytes.length,
        sha256: fileDigest(bytes),
      },
      key,
    );
    expect(conflict.status).toBe(409);
    expect(
      (await readdir(fixture.filesRoot)).filter((name) => /^[a-f0-9-]{36}$/.test(name)),
    ).toEqual([first.id]);
  });

  it("T-AC-57 hides private object metadata and bytes from another app user", async () => {
    const { file } = await committedFile(fixture, cookie);
    const stranger = await fixture.register({
      name: "Different synthetic user",
      email: "other@example.test",
      password: "Different-synthetic-passphrase-192!",
    });
    for (const path of [`/files/${file.id}`, `/files/${file.id}/download`])
      expect((await fixture.request(path, { headers: { cookie: stranger.cookie } })).status).toBe(
        404,
      );
    const list = await fixture.request("/files", { headers: { cookie: stranger.cookie } });
    expect(await list.json()).toEqual({ files: [], nextCursor: null });
    expect(
      (
        await fileJson(fixture, stranger.cookie, `/files/${file.id}/grants`, {
          expectedRevision: file.revision,
        })
      ).status,
    ).toBe(404);
  });

  it("T-AC-57 denies anonymous file reads and writes without allocating an object", async () => {
    const { file } = await committedFile(fixture, cookie);
    expect((await fixture.request(`/files/${file.id}/download`)).status).toBe(401);
    const before = await readdir(fixture.filesRoot);
    expect(
      (
        await fileJson(fixture, "", "/files", {
          name: "denied.txt",
          contentType: "text/plain",
          size: 1,
        })
      ).status,
    ).toBe(401);
    expect(await readdir(fixture.filesRoot)).toEqual(before);
  });

  it.each(["../escape", "nested/name", "nested\\name", "bad\u0000name"])(
    "T-AC-57 refuses unsafe display name %j without a filesystem effect",
    async (name) => {
      const before = await readdir(fixture.filesRoot);
      const response = await fileJson(fixture, cookie, "/files", {
        name,
        contentType: "text/plain",
        size: 1,
      });
      expect(response.status).toBe(422);
      expect(await readdir(fixture.filesRoot)).toEqual(before);
    },
  );

  it("T-AC-57 refuses object hard links without reading their foreign target", async () => {
    const { file } = await committedFile(fixture, cookie);
    const foreign = join(fixture.root, "foreign-bytes");
    await writeFile(foreign, "foreign bytes must stay private");
    await unlink(join(fixture.filesRoot, file.id));
    await link(foreign, join(fixture.filesRoot, file.id));
    const response = await fixture.request(`/files/${file.id}/download`, { headers: { cookie } });
    expect(response.status).toBe(409);
    expect(await response.text()).not.toContain("foreign bytes");
    expect(await readFile(foreign, "utf8")).toBe("foreign bytes must stay private");
  });

  it("T-AC-57 refuses a linked storage root rather than adopting another directory", async () => {
    const before = await readdir(fixture.filesRoot);
    const target = join(fixture.root, "linked-storage");
    await symlink(fixture.filesRoot, target, "junction");
    await expect(backendFixture({ filesRoot: target })).rejects.toThrow();
    expect(await readdir(fixture.filesRoot)).toEqual(before);
  });

  it("T-AC-56 rejects bytes beyond declared size before publishing a committed object", async () => {
    const initial = await initiateFile(fixture, cookie, new Uint8Array(1));
    const response = await appendFile(fixture, cookie, initial, new Uint8Array(2));
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
    const retained = FileView.parse(
      await (await fixture.request(`/files/${initial.id}`, { headers: { cookie } })).json(),
    );
    expect(retained.offset).toBe(0);
    expect(retained.status).toBe("uploading");
  });

  it("T-AC-57 serves only an exact bounded requested byte range", async () => {
    const { file } = await committedFile(fixture, cookie, "0123456789");
    const response = await fixture.request(`/files/${file.id}/download`, {
      headers: { cookie, range: "bytes=2-5" },
    });
    expect(response.status).toBe(206);
    expect(response.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(await response.text()).toBe("2345");
    expect(
      (
        await fixture.request(`/files/${file.id}/download`, {
          headers: { cookie, range: "bytes=0-1,3-4" },
        })
      ).status,
    ).toBe(416);
  });

  it("T-AC-57 expires exact session-bound download access and revokes it on file deletion", async () => {
    const { file } = await committedFile(fixture, cookie);
    const granted = await fileJson(fixture, cookie, `/files/${file.id}/grants`, {
      expectedRevision: file.revision,
      expiresInMs: 1000,
    });
    expect(granted.status).toBe(201);
    const grant = (await granted.json()) as { id: string; url: string; expiresAt: string };
    const path = new URL(grant.url, fixture.baseUrl).pathname.replace("/api/app/v1", "");
    expect((await fixture.request(path)).status).toBe(401);
    expect((await fixture.request(path, { headers: { cookie } })).status).toBe(200);
    fixture.advance(1100);
    expect((await fixture.request(path, { headers: { cookie } })).status).toBe(404);
    const removed = await fixture.request(`/files/${file.id}`, {
      method: "DELETE",
      headers: { cookie, "content-type": "application/json", "idempotency-key": randomUUID() },
      body: JSON.stringify({ expectedRevision: file.revision }),
    });
    expect(removed.status).toBe(200);
    expect(
      (await fixture.request(`/files/${file.id}/download`, { headers: { cookie } })).status,
    ).toBe(404);
  });

  it("T-AC-55 fences upload completion when lifecycle is held and preserves uncommitted bytes", async () => {
    const bytes = new TextEncoder().encode("held upload");
    const initial = await initiateFile(fixture, cookie, bytes);
    const appended = FileView.parse(
      await (await appendFile(fixture, cookie, initial, bytes)).json(),
    );
    fixture.lifecycle.available = false;
    fixture.lifecycle.epoch++;
    const complete = await fileJson(fixture, cookie, `/files/${initial.id}/complete`, {
      expectedRevision: appended.revision,
    });
    expect(complete.status).toBe(423);
    fixture.lifecycle.available = true;
    expect(
      FileView.parse(
        await (await fixture.request(`/files/${initial.id}`, { headers: { cookie } })).json(),
      ).status,
    ).toBe("uploading");
  });
});
